TS = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")

# ---------------- Evidence ----------------
def ev(id, source, query, result, method):
    return {"id": id, "source": source, "query": query, "result": result,
            "validation_method": method, "timestamp": TS}

