# ---------------- Mappings ----------------
def mp(id, term_id, table, column, grain, validation, semantic_filter="", agg=""):
    m = {"id": id, "term_id": term_id, "database_source": DB, "table": table, "column": column,
         "grain": grain, "validation": validation}
    if semantic_filter: m["semantic_filter"] = semantic_filter
    if agg: m["aggregation_semantics"] = agg
    return m

