    mp("map_order", "term_order", "orders", "order_id", "one row per order", "ev_payment_grain: 3000 orders; ev_status_enum", agg="count of distinct orders"),
    mp("map_valid_order", "term_valid_order", "orders", "status", "one row per order", "ev_valid_order_payment: status 1,2,3 orders are exactly those with a successful payment", semantic_filter="only orders in paid, shipped or delivered status", agg="count of distinct qualifying orders"),
